import{_ as t,c as a,o as h,a2 as i}from"./chunks/framework.B7el9cAC.js";const u=JSON.parse('{"title":"Mục 6.9 – Ôn Tập Chương 6: Đạo Đức & Nghề IT","description":"","frontmatter":{},"headers":[],"relativePath":"chuong-6/6.9-on-tap.md","filePath":"chuong-6/6.9-on-tap.md","lastUpdated":1775336269000}'),o={name:"chuong-6/6.9-on-tap.md"};function s(g,n,r,c,l,e){return h(),a("div",null,[...n[0]||(n[0]=[i(`<h1 id="muc-6-9-–-on-tap-chuong-6-đao-đuc-nghe-it" tabindex="-1">Mục 6.9 – Ôn Tập Chương 6: Đạo Đức &amp; Nghề IT <a class="header-anchor" href="#muc-6-9-–-on-tap-chuong-6-đao-đuc-nghe-it" aria-label="Permalink to &quot;Mục 6.9 – Ôn Tập Chương 6: Đạo Đức &amp; Nghề IT&quot;">​</a></h1><blockquote><p><strong>Chương 6: Đạo đức &amp; Nghề IT</strong></p></blockquote><hr><h2 id="🔹-1-tom-tat-toan-bo-chuong-6" tabindex="-1">🔹 1. TÓM TẮT TOÀN BỘ CHƯƠNG 6 <a class="header-anchor" href="#🔹-1-tom-tat-toan-bo-chuong-6" aria-label="Permalink to &quot;🔹 1. TÓM TẮT TOÀN BỘ CHƯƠNG 6&quot;">​</a></h2><h3 id="so-đo-tong-quan-chuong-6" tabindex="-1">Sơ đồ tổng quan Chương 6 <a class="header-anchor" href="#so-đo-tong-quan-chuong-6" aria-label="Permalink to &quot;Sơ đồ tổng quan Chương 6&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CHƯƠNG 6: ĐẠO ĐỨC &amp; NGHỀ IT</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── 6.1 VĂN HÓA MẠNG</span></span>
<span class="line"><span>│     ├── Netiquette = văn hóa ứng xử trên internet</span></span>
<span class="line"><span>│     ├── Cyberbullying: Harassment, Flaming, Outing, Exclusion, Impersonation, Trolling</span></span>
<span class="line"><span>│     ├── 10 quy tắc ứng xử trên mạng</span></span>
<span class="line"><span>│     └── Xử lý khi bị bắt nạt: Không phản ứng → Lưu bằng chứng → Block → Report → Báo người lớn</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── 6.2 AN TOÀN THÔNG TIN</span></span>
<span class="line"><span>│     ├── CIA Triad: Confidentiality (Bí mật) – Integrity (Toàn vẹn) – Availability (Sẵn sàng)</span></span>
<span class="line"><span>│     ├── Hacker: White Hat (hợp pháp), Black Hat (tội phạm), Grey Hat (mập mờ)</span></span>
<span class="line"><span>│     ├── Malware: Virus, Worm, Trojan, Ransomware, Spyware, Adware</span></span>
<span class="line"><span>│     ├── Phishing = giả mạo để lừa nhập thông tin</span></span>
<span class="line"><span>│     ├── Mật khẩu mạnh: ≥12 ký tự, hoa + thường + số + ký tự đặc biệt</span></span>
<span class="line"><span>│     └── Biện pháp: 2FA, cập nhật phần mềm, backup, không click link lạ</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── 6.3 NGHỀ IT</span></span>
<span class="line"><span>│     ├── Phần cứng (Hardware Engineer): chip, bo mạch, thiết bị</span></span>
<span class="line"><span>│     ├── Phần mềm (Software Engineer): code, ứng dụng, website</span></span>
<span class="line"><span>│     ├── Nghề IT phổ biến: Web Dev, Mobile Dev, AI Engineer, Security, Data Scientist, DevOps</span></span>
<span class="line"><span>│     └── Con đường: Học nền tảng → Chọn hướng → Dự án → Thực tập → Đi làm</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── 6.4 LUẬT AN NINH MẠNG</span></span>
<span class="line"><span>│     ├── Luật 24/2018/QH14, hiệu lực 01/01/2019</span></span>
<span class="line"><span>│     ├── Nghiêm cấm: tin sai sự thật, xúc phạm, hack hệ thống, tống tiền</span></span>
<span class="line"><span>│     ├── Mức phạt: 10-30 triệu (hành chính) đến tù giam (hình sự)</span></span>
<span class="line"><span>│     └── Nền tảng xóa nội dung vi phạm trong 24 giờ</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── 6.5 BẢN QUYỀN PHẦN MỀM</span></span>
<span class="line"><span>│     ├── Proprietary (Độc quyền), Freeware (Miễn phí dùng), Open Source (Mã nguồn mở)</span></span>
<span class="line"><span>│     ├── GPL: copyleft – phái sinh cũng phải GPL</span></span>
<span class="line"><span>│     ├── MIT: thoải mái nhất – được dùng thương mại</span></span>
<span class="line"><span>│     ├── Phần mềm lậu: vi phạm pháp luật + chứa malware</span></span>
<span class="line"><span>│     └── Thay thế miễn phí hợp pháp: LibreOffice, GIMP, 7-Zip</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── 6.6 QUYỀN RIÊNG TƯ SỐ</span></span>
<span class="line"><span>│     ├── Quyền kiểm soát thông tin cá nhân trên môi trường số</span></span>
<span class="line"><span>│     ├── Dữ liệu cá nhân nhạy cảm: CMND, ngân hàng, sức khỏe, sinh trắc học</span></span>
<span class="line"><span>│     ├── Nghị định 13/2023: bảo vệ dữ liệu cá nhân, hiệu lực 01/07/2023</span></span>
<span class="line"><span>│     ├── Filter Bubble = bong bóng thông tin cá nhân hóa</span></span>
<span class="line"><span>│     └── &quot;Nếu sản phẩm miễn phí, bạn là sản phẩm&quot;</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── 6.7 SỨC KHỎE KHI DÙNG MÁY TÍNH</span></span>
<span class="line"><span>│     ├── Ergonomics = công thái học, thiết kế không gian làm việc đúng cách</span></span>
<span class="line"><span>│     ├── CVS (Computer Vision Syndrome) = mỏi mắt do màn hình</span></span>
<span class="line"><span>│     ├── Quy tắc 20-20-20: 20 phút → vật 20 feet → 20 giây</span></span>
<span class="line"><span>│     ├── Text neck: cúi 60° = 27kg lên cột sống cổ</span></span>
<span class="line"><span>│     ├── Blue light → ức chế melatonin → khó ngủ</span></span>
<span class="line"><span>│     └── Khoảng cách mắt – màn hình: 50-70cm</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>└── 6.8 TÁC ĐỘNG CNTT ĐẾN XÃ HỘI</span></span>
<span class="line"><span>      ├── Tích cực: giáo dục bình đẳng, y tế tiên tiến, kinh tế phát triển</span></span>
<span class="line"><span>      ├── Tiêu cực: mất việc do tự động hóa, khoảng cách số, tin giả, deepfake</span></span>
<span class="line"><span>      ├── Digital Divide = khoảng cách số giữa người có/không có công nghệ</span></span>
<span class="line"><span>      ├── Deepfake = video/âm thanh giả mạo bằng AI</span></span>
<span class="line"><span>      └── Cách mạng 4.0 = IoT + AI + Big Data + Cloud + Blockchain</span></span></code></pre></div><hr><h2 id="🔹-2-bang-tom-tat-cac-khai-niem-quan-trong" tabindex="-1">🔹 2. BẢNG TÓM TẮT CÁC KHÁI NIỆM QUAN TRỌNG <a class="header-anchor" href="#🔹-2-bang-tom-tat-cac-khai-niem-quan-trong" aria-label="Permalink to &quot;🔹 2. BẢNG TÓM TẮT CÁC KHÁI NIỆM QUAN TRỌNG&quot;">​</a></h2><h3 id="nhom-1-van-hoa-mang-an-toan-thong-tin" tabindex="-1">Nhóm 1: Văn hóa mạng &amp; An toàn thông tin <a class="header-anchor" href="#nhom-1-van-hoa-mang-an-toan-thong-tin" aria-label="Permalink to &quot;Nhóm 1: Văn hóa mạng &amp; An toàn thông tin&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Khái niệm</th><th>Định nghĩa ngắn gọn</th></tr></thead><tbody><tr><td><strong>Netiquette</strong></td><td>Quy tắc ứng xử văn minh trên internet</td></tr><tr><td><strong>Cyberbullying</strong></td><td>Bắt nạt trực tuyến – cố ý, lặp lại, qua thiết bị số</td></tr><tr><td><strong>Phishing</strong></td><td>Giả mạo email/website để lấy thông tin đăng nhập</td></tr><tr><td><strong>Ransomware</strong></td><td>Mã hóa dữ liệu, đòi tiền chuộc</td></tr><tr><td><strong>2FA</strong></td><td>Xác thực 2 yếu tố – bảo vệ tài khoản bằng OTP thêm</td></tr><tr><td><strong>CIA Triad</strong></td><td>Bí mật + Toàn vẹn + Sẵn sàng – 3 nguyên tắc an toàn TT</td></tr><tr><td><strong>White Hat</strong></td><td>Hacker mũ trắng – bảo vệ hệ thống hợp pháp</td></tr><tr><td><strong>Black Hat</strong></td><td>Hacker mũ đen – tấn công trái phép</td></tr></tbody></table><h3 id="nhom-2-phap-ly-ban-quyen" tabindex="-1">Nhóm 2: Pháp lý &amp; Bản quyền <a class="header-anchor" href="#nhom-2-phap-ly-ban-quyen" aria-label="Permalink to &quot;Nhóm 2: Pháp lý &amp; Bản quyền&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Khái niệm</th><th>Định nghĩa ngắn gọn</th></tr></thead><tbody><tr><td><strong>Luật An ninh mạng</strong></td><td>Luật 24/2018, hiệu lực 01/01/2019</td></tr><tr><td><strong>Proprietary software</strong></td><td>Phần mềm độc quyền – phải mua/thuê</td></tr><tr><td><strong>Open Source</strong></td><td>Mã nguồn mở – được xem, sửa code (có điều kiện)</td></tr><tr><td><strong>GPL</strong></td><td>Giấy phép copyleft – phái sinh phải là GPL</td></tr><tr><td><strong>MIT License</strong></td><td>Giấy phép thoải mái nhất trong open source</td></tr><tr><td><strong>Software Piracy</strong></td><td>Dùng/phân phối phần mềm vi phạm bản quyền</td></tr></tbody></table><h3 id="nhom-3-rieng-tu-suc-khoe-so" tabindex="-1">Nhóm 3: Riêng tư &amp; Sức khỏe số <a class="header-anchor" href="#nhom-3-rieng-tu-suc-khoe-so" aria-label="Permalink to &quot;Nhóm 3: Riêng tư &amp; Sức khỏe số&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Khái niệm</th><th>Định nghĩa ngắn gọn</th></tr></thead><tbody><tr><td><strong>Digital Privacy</strong></td><td>Quyền kiểm soát thông tin cá nhân trên môi trường số</td></tr><tr><td><strong>Data Breach</strong></td><td>Rò rỉ dữ liệu do bị tấn công/hack</td></tr><tr><td><strong>Filter Bubble</strong></td><td>Bong bóng thông tin – thuật toán chỉ cho xem nội dung phù hợp</td></tr><tr><td><strong>Ergonomics</strong></td><td>Công thái học – thiết kế không gian làm việc đúng cách</td></tr><tr><td><strong>CVS</strong></td><td>Hội chứng mỏi mắt do màn hình</td></tr><tr><td><strong>Blue light</strong></td><td>Ánh sáng xanh ức chế melatonin, gây khó ngủ</td></tr><tr><td><strong>20-20-20 rule</strong></td><td>20 phút nhìn màn hình → 20 feet → 20 giây</td></tr><tr><td><strong>Text Neck</strong></td><td>Cúi điện thoại 60° = 27kg lên cột sống cổ</td></tr></tbody></table><h3 id="nhom-4-nghe-it-tac-đong-xa-hoi" tabindex="-1">Nhóm 4: Nghề IT &amp; Tác động xã hội <a class="header-anchor" href="#nhom-4-nghe-it-tac-đong-xa-hoi" aria-label="Permalink to &quot;Nhóm 4: Nghề IT &amp; Tác động xã hội&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Khái niệm</th><th>Định nghĩa ngắn gọn</th></tr></thead><tbody><tr><td><strong>Hardware Engineer</strong></td><td>Kỹ sư phần cứng – chip, bo mạch, thiết bị</td></tr><tr><td><strong>Software Engineer</strong></td><td>Kỹ sư phần mềm – code, ứng dụng, website</td></tr><tr><td><strong>Digital Divide</strong></td><td>Khoảng cách số – bất bình đẳng tiếp cận CNTT</td></tr><tr><td><strong>Deepfake</strong></td><td>Video/âm thanh giả mạo người thật bằng AI</td></tr><tr><td><strong>Industry 4.0</strong></td><td>Cách mạng 4.0: IoT + AI + Big Data + Cloud + Blockchain</td></tr><tr><td><strong>Digital Transformation</strong></td><td>Chuyển đổi số – tích hợp CNTT vào mọi lĩnh vực</td></tr></tbody></table><hr><h2 id="🔹-3-cac-con-so-va-moc-thoi-gian-can-nho" tabindex="-1">🔹 3. CÁC CON SỐ VÀ MỐC THỜI GIAN CẦN NHỚ <a class="header-anchor" href="#🔹-3-cac-con-so-va-moc-thoi-gian-can-nho" aria-label="Permalink to &quot;🔹 3. CÁC CON SỐ VÀ MỐC THỜI GIAN CẦN NHỚ&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Con số / Mốc thời gian</th><th>Ý nghĩa</th></tr></thead><tbody><tr><td><strong>01/01/2019</strong></td><td>Luật An ninh mạng có hiệu lực</td></tr><tr><td><strong>01/07/2023</strong></td><td>Nghị định 13/2023 (Bảo vệ DLCN) có hiệu lực</td></tr><tr><td><strong>10-20 triệu</strong></td><td>Phạt đăng tin sai sự thật</td></tr><tr><td><strong>20-30 triệu</strong></td><td>Phạt xúc phạm danh dự trên mạng</td></tr><tr><td><strong>24 giờ</strong></td><td>Thời hạn nền tảng xóa nội dung vi phạm</td></tr><tr><td><strong>12 ký tự</strong></td><td>Độ dài tối thiểu mật khẩu mạnh</td></tr><tr><td><strong>20-20-20</strong></td><td>Quy tắc bảo vệ mắt khi dùng máy tính</td></tr><tr><td><strong>50-70cm</strong></td><td>Khoảng cách mắt – màn hình đúng chuẩn</td></tr><tr><td><strong>27 kg</strong></td><td>Lực tác động lên cổ khi cúi điện thoại 60°</td></tr><tr><td><strong>47%</strong></td><td>Tỷ lệ công việc có nguy cơ bị tự động hóa (McKinsey)</td></tr></tbody></table><hr><h2 id="🔹-4-đe-on-tap-tong-hop" tabindex="-1">🔹 4. ĐỀ ÔN TẬP TỔNG HỢP <a class="header-anchor" href="#🔹-4-đe-on-tap-tong-hop" aria-label="Permalink to &quot;🔹 4. ĐỀ ÔN TẬP TỔNG HỢP&quot;">​</a></h2><h3 id="phan-i-cau-hoi-trac-nghiem-chon-đap-an-đung-nhat" tabindex="-1">Phần I: Câu hỏi trắc nghiệm (chọn đáp án đúng nhất) <a class="header-anchor" href="#phan-i-cau-hoi-trac-nghiem-chon-đap-an-đung-nhat" aria-label="Permalink to &quot;Phần I: Câu hỏi trắc nghiệm (chọn đáp án đúng nhất)&quot;">​</a></h3><p><strong>Câu 1:</strong> &quot;Netiquette&quot; là ghép của hai từ tiếng Anh nào?</p><p>A. Network + Technique<br> B. Network + Etiquette<br> C. Net + Etiquette<br> D. Internet + Etiquette</p><blockquote><p>✅ <strong>Đáp án: B</strong> – Network + Etiquette</p></blockquote><hr><p><strong>Câu 2:</strong> Loại Cyberbullying nào liên quan đến việc lập tài khoản giả mạo danh tính người khác?</p><p>A. Harassment<br> B. Outing<br> C. Exclusion<br> D. Impersonation</p><blockquote><p>✅ <strong>Đáp án: D</strong> – Impersonation = giả mạo danh tính</p></blockquote><hr><p><strong>Câu 3:</strong> Trong mô hình CIA Triad, chữ &quot;A&quot; đại diện cho điều gì?</p><p>A. Authentication (Xác thực)<br> B. Authorization (Phân quyền)<br> C. Availability (Sẵn sàng)<br> D. Anonymity (Ẩn danh)</p><blockquote><p>✅ <strong>Đáp án: C</strong> – Availability = Tính sẵn sàng của dữ liệu</p></blockquote><hr><p><strong>Câu 4:</strong> Loại malware nào mã hóa dữ liệu của nạn nhân và đòi tiền chuộc?</p><p>A. Virus<br> B. Worm<br> C. Ransomware<br> D. Spyware</p><blockquote><p>✅ <strong>Đáp án: C</strong> – Ransomware = Ransom (tiền chuộc) + Software</p></blockquote><hr><p><strong>Câu 5:</strong> Mật khẩu nào sau đây mạnh nhất?</p><p>A. <code>12345678</code><br> B. <code>TenToiLaHung2009</code><br> C. <code>P@ssword123</code><br> D. <code>xK#9mP!2vR@qL7</code></p><blockquote><p>✅ <strong>Đáp án: D</strong> – Dài, không có nghĩa, kết hợp đủ loại ký tự</p></blockquote><hr><p><strong>Câu 6:</strong> Luật An ninh mạng Việt Nam có hiệu lực từ ngày nào?</p><p>A. 12/06/2018<br> B. 01/01/2019<br> C. 01/07/2023<br> D. 15/08/2020</p><blockquote><p>✅ <strong>Đáp án: B</strong> – 01/01/2019</p></blockquote><hr><p><strong>Câu 7:</strong> Phần mềm nào là ví dụ về Open Source?</p><p>A. Microsoft Windows<br> B. Adobe Photoshop<br> C. LibreOffice<br> D. WinRAR</p><blockquote><p>✅ <strong>Đáp án: C</strong> – LibreOffice là phần mềm mã nguồn mở. WinRAR là freeware (dùng thử/miễn phí nhưng không open source)</p></blockquote><hr><p><strong>Câu 8:</strong> &quot;Filter Bubble&quot; là hiện tượng gì?</p><p>A. Bộ lọc chặn nội dung xấu trên internet<br> B. Thuật toán chỉ hiển thị nội dung phù hợp với sở thích người dùng<br> C. Hệ thống lọc spam trong email<br> D. Tường lửa bảo vệ mạng gia đình</p><blockquote><p>✅ <strong>Đáp án: B</strong> – Bong bóng lọc/thông tin cá nhân hóa</p></blockquote><hr><p><strong>Câu 9:</strong> Quy tắc 20-20-20 được áp dụng để:</p><p>A. Kiểm tra mật khẩu 20 ký tự mỗi 20 ngày<br> B. Bảo vệ mắt: cứ 20 phút nhìn vật cách 20 feet trong 20 giây<br> C. Sao lưu dữ liệu 20 ngày một lần<br> D. Nghỉ giải lao 20 phút mỗi 20 tiếng làm việc</p><blockquote><p>✅ <strong>Đáp án: B</strong> – Quy tắc bảo vệ mắt</p></blockquote><hr><p><strong>Câu 10:</strong> &quot;Digital Divide&quot; (Khoảng cách số) là gì?</p><p>A. Sự khác biệt tốc độ internet giữa các nhà mạng<br> B. Bất bình đẳng giữa người có/không có khả năng tiếp cận CNTT<br> C. Khoảng cách giữa thế hệ game thủ PC và mobile<br> D. Sự khác biệt về giá điện thoại giữa các hãng</p><blockquote><p>✅ <strong>Đáp án: B</strong> – Khoảng cách về tiếp cận công nghệ</p></blockquote><hr><h3 id="phan-ii-cau-hoi-tu-luan-ngan" tabindex="-1">Phần II: Câu hỏi tự luận ngắn <a class="header-anchor" href="#phan-ii-cau-hoi-tu-luan-ngan" aria-label="Permalink to &quot;Phần II: Câu hỏi tự luận ngắn&quot;">​</a></h3><p><strong>Câu 11:</strong> Nêu 3 loại malware phổ biến và mô tả ngắn từng loại.</p><blockquote><p>✅ <strong>Đáp án:</strong></p><ol><li><strong>Virus:</strong> Tự sao chép và lây lan từ file sang file; cần &quot;ký chủ&quot; để tồn tại; thường phá hủy file, làm chậm máy.</li><li><strong>Ransomware:</strong> Mã hóa toàn bộ dữ liệu nạn nhân, đòi tiền chuộc (thường Bitcoin) để giải mã. Nguy hiểm nhất với dữ liệu quan trọng.</li><li><strong>Spyware:</strong> Âm thầm theo dõi hoạt động, ghi lại mật khẩu, thông tin tài khoản mà nạn nhân không hay biết.</li></ol></blockquote><hr><p><strong>Câu 12:</strong> Sự khác nhau giữa White Hat và Black Hat Hacker là gì?</p><blockquote><p>✅ <strong>Đáp án:</strong></p><ul><li><strong>White Hat Hacker:</strong> Chuyên gia bảo mật được thuê và ủy quyền hợp pháp để tìm lỗ hổng trong hệ thống, sau đó báo cáo để vá. Hoạt động hợp pháp, có hợp đồng.</li><li><strong>Black Hat Hacker:</strong> Kẻ tấn công mạng bất hợp pháp, không có quyền truy cập, mục đích là đánh cắp dữ liệu, gây hại, kiếm lợi phi pháp.</li><li>Điểm khác biệt chính: <strong>sự cho phép và mục đích</strong>.</li></ul></blockquote><hr><p><strong>Câu 13:</strong> Tại sao phần mềm crack lại nguy hiểm hơn &quot;chỉ vi phạm bản quyền&quot;?</p><blockquote><p>✅ <strong>Đáp án:</strong> Phần mềm crack nguy hiểm vì ngoài vi phạm pháp luật, còn có nguy cơ an toàn nghiêm trọng: (1) Người tạo crack thường cài thêm malware (trojan, ransomware, spyware) để kiếm lợi; (2) Không nhận cập nhật bảo mật – lỗ hổng bị khai thác; (3) Phải vô hiệu hóa cơ chế bảo vệ hệ điều hành để crack hoạt động; (4) Có thể đánh cắp mật khẩu và dữ liệu tài chính. Chi phí thật sự của &quot;miễn phí&quot; có thể là mất toàn bộ dữ liệu.</p></blockquote><hr><p><strong>Câu 14:</strong> Nêu 4 tác động tiêu cực của CNTT đến xã hội.</p><blockquote><p>✅ <strong>Đáp án:</strong></p><ol><li><strong>Mất việc làm do tự động hóa:</strong> Robot và AI thay thế lao động phổ thông.</li><li><strong>Khoảng cách số:</strong> Bất bình đẳng giữa người có/không có khả năng tiếp cận CNTT.</li><li><strong>Tin giả và Deepfake:</strong> Thông tin sai lệch lan nhanh, video giả mạo khó phân biệt.</li><li><strong>Vấn đề riêng tư và giám sát:</strong> Dữ liệu cá nhân bị thu thập, bán, hoặc bị rò rỉ.</li></ol></blockquote><hr><h3 id="phan-iii-cau-hoi-tinh-huong" tabindex="-1">Phần III: Câu hỏi tình huống <a class="header-anchor" href="#phan-iii-cau-hoi-tinh-huong" aria-label="Permalink to &quot;Phần III: Câu hỏi tình huống&quot;">​</a></h3><p><strong>Câu 15:</strong> Bạn nhận được email từ &quot;Vietcombank&quot; thông báo tài khoản bị khóa, yêu cầu click vào link <code>http://vietc0mbank-xacminh.xyz/login</code> để xác minh ngay.</p><ul><li><strong>a)</strong> Đây có phải email thật không? Dấu hiệu nào cho thấy đây là Phishing?</li><li><strong>b)</strong> Bạn nên làm gì?</li></ul><blockquote><p>✅ <strong>Đáp án:</strong><strong>a) Không phải email thật. Dấu hiệu Phishing:</strong></p><ul><li>Tên miền sai: <code>vietc0mbank-xacminh.xyz</code> (số 0 thay chữ o; đuôi <code>.xyz</code>; Vietcombank thật dùng <code>vietcombank.com.vn</code>)</li><li>Giao thức HTTP (không có HTTPS) – không bảo mật</li><li>Tạo cảm giác khẩn cấp, sợ hãi (&quot;bị khóa&quot;)</li><li>Yêu cầu xác minh qua link – ngân hàng thật không làm vậy</li></ul><p><strong>b) Hành động đúng:</strong></p><ol><li><strong>Không click link</strong> trong email</li><li><strong>Xóa email</strong> đó</li><li><strong>Mở trực tiếp app Vietcombank</strong> hoặc vào website chính thức để kiểm tra</li><li>Nếu lo ngại, gọi hotline Vietcombank trên thẻ ngân hàng của bạn</li></ol></blockquote><hr><p><strong>Câu 16:</strong> Bạn phát hiện bạn cùng lớp đang đăng bình luận xúc phạm, kèm ảnh riêng tư của một bạn khác lên Facebook. Theo đúng Luật An ninh mạng và đạo đức, bạn nên làm gì?</p><blockquote><p>✅ <strong>Đáp án:</strong></p><ol><li><strong>Không chia sẻ, không tham gia</strong> vào hành vi xúc phạm</li><li><strong>Lưu bằng chứng</strong> (screenshot bài đăng, URL)</li><li><strong>Report bài đăng</strong> lên Facebook vì vi phạm quyền riêng tư và cộng đồng</li><li><strong>Nói với nạn nhân</strong> để họ biết và có thể hành động (báo thầy cô, gia đình)</li><li><strong>Báo giáo viên chủ nhiệm</strong> hoặc ban giám hiệu nếu đây là học sinh cùng trường</li><li><strong>Pháp lý:</strong> Hành vi này vi phạm Điều 8 Luật An ninh mạng (xúc phạm danh dự, chia sẻ thông tin riêng tư trái phép) – người đăng có thể bị phạt hành chính 20-30 triệu đồng</li></ol></blockquote><hr><h2 id="🔹-5-bang-so-sanh-tong-hop-chuong-6" tabindex="-1">🔹 5. BẢNG SO SÁNH TỔNG HỢP CHƯƠNG 6 <a class="header-anchor" href="#🔹-5-bang-so-sanh-tong-hop-chuong-6" aria-label="Permalink to &quot;🔹 5. BẢNG SO SÁNH TỔNG HỢP CHƯƠNG 6&quot;">​</a></h2><h3 id="so-sanh-cac-hanh-vi-va-hau-qua-phap-ly" tabindex="-1">So sánh các hành vi và hậu quả pháp lý <a class="header-anchor" href="#so-sanh-cac-hanh-vi-va-hau-qua-phap-ly" aria-label="Permalink to &quot;So sánh các hành vi và hậu quả pháp lý&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Hành vi</th><th>Vi phạm gì</th><th>Mức phạt</th></tr></thead><tbody><tr><td>Đăng tin sai sự thật</td><td>Luật An ninh mạng, Điều 8</td><td>10-20 triệu đồng</td></tr><tr><td>Xúc phạm danh dự trên mạng</td><td>Luật An ninh mạng, Điều 8</td><td>20-30 triệu đồng</td></tr><tr><td>Dùng phần mềm crack</td><td>Luật Sở hữu trí tuệ</td><td>10-50 triệu đồng</td></tr><tr><td>Hack tài khoản người khác</td><td>Bộ luật Hình sự Điều 289</td><td>Phạt tù 1-5 năm</td></tr><tr><td>Chia sẻ ảnh riêng tư trái phép</td><td>Nghị định 13/2023</td><td>Phạt tiền, bồi thường</td></tr></tbody></table><h3 id="so-sanh-tong-hop-cac-giai-phap-bao-ve-ban-than" tabindex="-1">So sánh tổng hợp các giải pháp bảo vệ bản thân <a class="header-anchor" href="#so-sanh-tong-hop-cac-giai-phap-bao-ve-ban-than" aria-label="Permalink to &quot;So sánh tổng hợp các giải pháp bảo vệ bản thân&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Vấn đề</th><th>Giải pháp chính</th></tr></thead><tbody><tr><td>Tài khoản bị hack</td><td>Mật khẩu mạnh + 2FA + không click link lạ</td></tr><tr><td>Bị Cyberbullying</td><td>Không phản ứng → Lưu bằng chứng → Block → Report → Báo người lớn</td></tr><tr><td>Tin giả</td><td>Kiểm tra nguồn ≥2 nơi uy tín trước khi chia sẻ</td></tr><tr><td>Bị Phishing</td><td>Kiểm tra URL + không nhập thông tin theo link email</td></tr><tr><td>Mỏi mắt</td><td>Quy tắc 20-20-20 + điều chỉnh màn hình đúng</td></tr><tr><td>Đau lưng/cổ</td><td>Tư thế ngồi đúng + nghỉ giải lao mỗi 50-60 phút</td></tr><tr><td>Dữ liệu bị lộ</td><td>Không đăng thông tin nhạy cảm + cài đặt riêng tư</td></tr></tbody></table><hr><h2 id="🔹-6-ghi-nho-nhanh-toan-chuong-đi-thi" tabindex="-1">🔹 6. GHI NHỚ NHANH TOÀN CHƯƠNG (ĐI THI) <a class="header-anchor" href="#🔹-6-ghi-nho-nhanh-toan-chuong-đi-thi" aria-label="Permalink to &quot;🔹 6. GHI NHỚ NHANH TOÀN CHƯƠNG (ĐI THI)&quot;">​</a></h2><h3 id="van-hoa-mang-6-1" tabindex="-1">Văn hóa mạng (6.1) <a class="header-anchor" href="#van-hoa-mang-6-1" aria-label="Permalink to &quot;Văn hóa mạng (6.1)&quot;">​</a></h3><ul><li>✅ Netiquette = Network + Etiquette</li><li>✅ Cyberbullying = cố ý, lặp lại, qua thiết bị số</li><li>✅ 6 hình thức: Harassment, Flaming, <strong>Outing</strong>, Exclusion, <strong>Impersonation</strong>, Trolling</li><li>✅ Xử lý: Không phản ứng → Lưu bằng chứng → Block → Report → Người lớn</li></ul><h3 id="an-toan-thong-tin-6-2" tabindex="-1">An toàn thông tin (6.2) <a class="header-anchor" href="#an-toan-thong-tin-6-2" aria-label="Permalink to &quot;An toàn thông tin (6.2)&quot;">​</a></h3><ul><li>✅ CIA = Confidentiality + Integrity + Availability</li><li>✅ White Hat = hợp pháp; Black Hat = tội phạm</li><li>✅ Ransomware = mã hóa đòi tiền; Phishing = giả mạo lấy thông tin</li><li>✅ Mật khẩu mạnh: ≥12 ký tự, hoa + thường + số + ký tự đặc biệt</li></ul><h3 id="nghe-it-6-3" tabindex="-1">Nghề IT (6.3) <a class="header-anchor" href="#nghe-it-6-3" aria-label="Permalink to &quot;Nghề IT (6.3)&quot;">​</a></h3><ul><li>✅ Hardware = phần cứng; Software = phần mềm</li><li>✅ 10 nghề IT phổ biến: Web, Mobile, AI, Security, Data Scientist, DevOps...</li><li>✅ VN thiếu hụt nhân lực IT trầm trọng</li></ul><h3 id="luat-an-ninh-mang-6-4" tabindex="-1">Luật An ninh mạng (6.4) <a class="header-anchor" href="#luat-an-ninh-mang-6-4" aria-label="Permalink to &quot;Luật An ninh mạng (6.4)&quot;">​</a></h3><ul><li>✅ Luật 24/2018, hiệu lực 01/01/2019</li><li>✅ Phạt tin sai: 10-20 triệu; Phạt xúc phạm: 20-30 triệu</li><li>✅ Nền tảng xóa vi phạm trong 24 giờ</li></ul><h3 id="ban-quyen-phan-mem-6-5" tabindex="-1">Bản quyền phần mềm (6.5) <a class="header-anchor" href="#ban-quyen-phan-mem-6-5" aria-label="Permalink to &quot;Bản quyền phần mềm (6.5)&quot;">​</a></h3><ul><li>✅ Open Source ≠ miễn phí hoàn toàn – có điều kiện giấy phép</li><li>✅ GPL = copyleft; MIT = thoải mái nhất</li><li>✅ Phần mềm lậu = vi phạm pháp luật + nguy hiểm (malware)</li></ul><h3 id="quyen-rieng-tu-6-6" tabindex="-1">Quyền riêng tư (6.6) <a class="header-anchor" href="#quyen-rieng-tu-6-6" aria-label="Permalink to &quot;Quyền riêng tư (6.6)&quot;">​</a></h3><ul><li>✅ &quot;Sản phẩm miễn phí → bạn là sản phẩm&quot;</li><li>✅ Nghị định 13/2023, hiệu lực 01/07/2023</li><li>✅ Filter Bubble = thuật toán chỉ cho xem nội dung bạn thích</li></ul><h3 id="suc-khoe-6-7" tabindex="-1">Sức khỏe (6.7) <a class="header-anchor" href="#suc-khoe-6-7" aria-label="Permalink to &quot;Sức khỏe (6.7)&quot;">​</a></h3><ul><li>✅ 20-20-20; Khoảng cách mắt-màn hình: 50-70cm</li><li>✅ Text neck: 60° = 27kg; Blue light → khó ngủ</li><li>✅ Tắt màn hình 1 giờ trước ngủ</li></ul><h3 id="tac-đong-cntt-6-8" tabindex="-1">Tác động CNTT (6.8) <a class="header-anchor" href="#tac-đong-cntt-6-8" aria-label="Permalink to &quot;Tác động CNTT (6.8)&quot;">​</a></h3><ul><li>✅ Tích cực: giáo dục, y tế, kinh tế, kết nối</li><li>✅ Tiêu cực: mất việc, khoảng cách số, tin giả, riêng tư</li><li>✅ Deepfake = AI tạo video giả mạo người thật</li><li>✅ Cách mạng 4.0 = IoT + AI + Big Data + Cloud + Blockchain</li></ul>`,106)])])}const d=t(o,[["render",s]]);export{u as __pageData,d as default};
